import Foundation

// This is an example of a function signature.
// It does not include types for the parameters and return value, which
// allows any type to be used.
func someFunction(_ someParameter: Int, thenSomeOtherParameter: Bool) -> String {
return ""
}

// Here's an example of a function call. Note that the parameter names
// don't have to match the function parameter names, but the order does.
someFunction(5, thenSomeOtherParameter: true)

// Here's an example of a function call with named arguments. This
// allows you to provide the arguments in any order, and also lets you
// omit arguments you don't care about.
someFunction(thenSomeOtherParameter: true, someParameter: 5)

// Functions can also be used as parameters to other functions.
func doSomethingUseful(item: Any) {
print("I'm useful!")
}

func callDoSomethingUsefulWith(item: Any, thenSomeOtherParameter: Bool) {
doSomethingUseful(item: item)
}

callDoSomethingUsefulWith(item: 5, thenSomeOtherParameter: true)

// Functions can also be used as return values.
func makeIncrementer() -> ((Int) -> Int) {
func addOne(number: Int) -> Int {
return number + 1
}
return addOne
}

let increment = makeIncrementer()
print(increment(7))

// Functions can also be used as closures. Closures are similar to
// functions, but can capture and store references to any constants and
// variables from the context in which they are defined. In effect, this
// means that closures can "escape" their original scope.
var employees = [String]()
employees.append("John Appleseed")
employees.append("Jack Bauer")
employees.append("Frank Gump")

// Here's an example of a closure that takes no arguments and returns no
// value. This is the simplest kind of closure.
employees.map {
print("\($0) has a birthday today!")
}

// Here's an example of a closure that takes one argument and returns a
// value. Note that the closure's parameter name doesn't have to match
// the parameter name in the function call.
employees.map { employee in
print("\(employee) has a birthday today!")
}

